-- ⑤ S2 大米 207 件掉落 INSERT（杂项 17 件按裁定不录；official_item_id 列为 text 型）
 （1分钟冷却）$$, ARRAY['力量'], NULL, '{"力量": 61}'::jsonb, NULL, '{"mythic": {"力量": 121}, "normal": {"力量": 89}, "heroic": {"力量": 104}}'::jsonb, NULL, NULL, 7956734);

主要目标还将在接下来的15秒内，额外承受11,505点自然伤害。 $$, ARRAY['智力'], NULL, '{"智力": 61}'::jsonb, NULL, '{"mythic": {"智力": 121}, "normal": {"智力": 89}, "heroic": {"智力": 104}}'::jsonb, NULL, NULL, 7956742);

如果有盟友踩中并吸收蘑菇，将额外恢复21,813点生命值。$$, ARRAY['智力'], NULL, '{"智力": 7}'::jsonb, NULL, '{"mythic": {"智力": 121}, "normal": {"智力": 59}, "heroic": {"智力": 104}}'::jsonb, NULL, NULL, 1029746);

如果生命值降至25%以下，储备会爆发，消耗所有印记形成寒冰屏障，每层印记可吸收48,227点伤害，持续10秒。$$, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 7578261);

附近获得纳洛拉克青睐的盟友将受到激励，在10秒内移动速度提高25%。$$, NULL, ARRAY['爆击'], NULL, '{"爆击": 10}'::jsonb, NULL, '{"mythic": {"爆击": 119}, "normal": {"爆击": 73}, "heroic": {"爆击": 110}}'::jsonb, NULL, 7578259);

护盾效果结束或破碎时，能量会产生爆发并对附近敌人造成火焰伤害，由这些敌人均摊。 （1分钟 30秒冷却）$$, ARRAY['敏捷','力量'], NULL, '{"敏捷": 7}'::jsonb, NULL, '{"mythic": {"力量": 121, "敏捷": 121}, "normal": {"力量": 59, "敏捷": 59}, "heroic": {"力量": 104, "敏捷": 104}}'::jsonb, NULL, NULL, 841218);

在此期间，你的每次攻击都会使爆击额外提高21，最多可叠加5层。$$, ARRAY['敏捷','力量'], NULL, '{"敏捷": 7}'::jsonb, NULL, '{"mythic": {"力量": 121, "敏捷": 121}, "normal": {"力量": 59, "敏捷": 59}, "heroic": {"力量": 104, "敏捷": 104}}'::jsonb, NULL, NULL, 3566862);

如果目标生命值低于50%，光明之花会在绚烂光芒中完全绽放，立即为其恢复126,345点生命值。 （1分钟 30秒冷却）$$, ARRAY['智力'], NULL, '{"智力": 7}'::jsonb, NULL, '{"mythic": {"智力": 121}, "normal": {"智力": 59}, "heroic": {"智力": 104}}'::jsonb, NULL, NULL, 7578262);

你的伤害法术和技能有几率召唤一束辉光在附近降下，当你站在其中时会给予你精通提高166的赐福。
$$, ARRAY['敏捷','智力'], NULL, '{"敏捷": 7}'::jsonb, '{"精通": 22}'::jsonb, '{"mythic": {"敏捷": 121, "智力": 121}, "normal": {"敏捷": 59, "智力": 59}, "heroic": {"敏捷": 104, "智力": 104}}'::jsonb, NULL, NULL, 132862);

光诞鞭笞者随即枯萎，爆裂出灌注光明的汁液，对附近敌人造成总计10,043点神圣伤害并由所有目标分摊。$$, ARRAY['敏捷','智力','力量'], NULL, '{"敏捷": 7}'::jsonb, NULL, '{"mythic": {"智力": 121, "力量": 121, "敏捷": 121}, "normal": {"智力": 59, "力量": 59, "敏捷": 59}, "heroic": {"智力": 104, "力量": 104, "敏捷": 104}}'::jsonb, NULL, NULL, 134218);

$$, ARRAY['敏捷','智力','力量'], NULL, '{"敏捷": 10}'::jsonb, NULL, '{"normal": {"智力": 16, "力量": 16, "敏捷": 16}, "mythic": {"智力": 121, "力量": 121, "敏捷": 121}, "timewalking": {"智力": 62, "力量": 62, "敏捷": 62}, "heroic": {"智力": 104, "力量": 104, "敏捷": 104}}'::jsonb, NULL, NULL, 4509422);
伤口存在期间，你的伤害性法术有很高的几率加深伤口，额外造成5,423点自然伤害。 （2分钟冷却）$$, ARRAY['智力'], NULL, '{"智力": 6}'::jsonb, NULL, '{"normal": {"智力": 13}, "mythic": {"智力": 121}, "timewalking": {"智力": 62}, "heroic": {"智力": 104}}'::jsonb, NULL, NULL, 1658496);

